const HABITS=['проверяет сообщения, даже когда телефон лежит экраном вниз','пишет «принято» только после третьего напоминания','хранит важные размеры на обороте пропуска','считает голосовое разновидностью исполнительной документации','не доверяет лестницам, подписанным маркером','узнаёт срочную задачу по числу восклицательных знаков','приносит свой удлинитель и чужое спокойствие','находит нужный файл, если никто не менял его название','помнит, кто обещал выйти в субботу','открывает чертёж сразу на правильной версии','считает перекур частью оперативного планирования','отвечает на претензию фотографией без подписи','молчит так, что подрядчик сам обещает ускориться','ведёт список переделок в блокноте «готово»','знает, где лежит рулетка, но не говорит без запроса','при слове «оптимизация» проверяет остаток денег','не спорит с технадзором до кофе','отличает допработу от подарка заказчику','сохраняет все письма и некоторые обиды','уверенно кивает, когда никто не понял задачу','приносит каску, зарядку и одно плохое предчувствие','считает фотографию актом, если на ней видна дата','знает поставщика, который ещё берёт трубку','не уходит, пока не выяснит, кто выключил свет','пишет отчёт так, будто его будут читать','боится только скрытых работ и открытых обязательств','выглядит занятым рядом с любой стремянкой','слышит «давайте без проекта» за две комнаты','помнит цену ошибки лучше цены материала','считает хорошим днём тот, когда ничего не ломали повторно'];
const ENDINGS=['Коллеги ценят это качество, бухгалтерия пока наблюдает','На прошлом объекте это почти сработало','Руководство называет это потенциалом, прораб — обстоятельством','В резюме навык записан короче и без свидетелей','Подрядчики уважают этот подход на безопасном расстоянии','Заказчик однажды даже сказал спасибо, но письмо не сохранилось','Слабое место — задачи со словами «там всё просто»','Сильная сторона — пережитые понедельники'];

export function generateBiography(seed,role,genderPresentation){const feminine=genderPresentation==='feminine',opening=pickSeeded(createSeededRng(`${seed}:bio:opening`),ROLE_OPENINGS[role]||ROLE_OPENINGS.worker),habit=pickSeeded(createSeededRng(`${seed}:bio:habit`),HABITS),ending=pickSeeded(createSeededRng(`${seed}:bio:ending`),ENDINGS);return{summary:`${opening}. ${feminine?'Она':'Он'} ${habit}. ${ending}.`,reputation:ending,fragments:{opening,habit,ending}}}
export const BIOGRAPHY_VARIANT_FLOOR=Object.values(ROLE_OPENINGS).reduce((sum,list)=>sum+list.length,0)*HABITS.length*ENDINGS.length;
